<?php
require_once 'includes/auth.php';require_once 'includes/db.php';require_login();
$q=trim($_GET['q']??'');$equipeId=filter_input(INPUT_GET,'equipe_id',FILTER_VALIDATE_INT);$sql="SELECT p.*,e.sigla,e.nome equipe_nome FROM patinadores p LEFT JOIN equipes e ON e.id=p.equipe_id WHERE p.ativo=1";$args=[];if($equipeId){$sql.=' AND p.equipe_id=?';$args[]=$equipeId;}if($q!==''){$sql.=' AND (p.nome LIKE ? OR p.pais LIKE ? OR p.disciplina LIKE ? OR e.nome LIKE ? OR e.pais LIKE ?)';$like="%$q%";$args=array_merge($args,[$like,$like,$like,$like,$like]);} $sql.=' ORDER BY p.nome';$st=db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$teamTitle='';if($equipeId){$ts=db()->prepare('SELECT pais,nome FROM equipes WHERE id=?');$ts->execute([$equipeId]);$teamTitle=$ts->fetchColumn(0) ?: '';}$pageTitle='Patinadores';require 'includes/header.php'; ?>
<div class="page-intro"><span class="eyebrow">ATHLETE DIRECTORY</span><h1><?= $teamTitle!==''?'Atletas da <em>'.e($teamTitle).'</em>':'Conheça os <em>patinadores.</em>' ?></h1><p>Perfis de atletas de destaque, suas federações, disciplinas e trajetórias no gelo.</p></div><form class="search-bar" method="get"><?php if($equipeId): ?><input type="hidden" name="equipe_id" value="<?= (int)$equipeId ?>"><?php endif; ?><input name="q" value="<?= e($q) ?>" placeholder="Buscar atleta, país ou disciplina..."><button class="btn btn-dark" type="submit">Buscar ↗</button></form><div class="athlete-grid"><?php if(!$rows): ?><div class="panel"><h3>Nenhum patinador encontrado</h3><p class="muted">Esta equipe ainda não possui atletas cadastrados.</p><a class="text-link" href="equipes.php">Voltar às equipes ↗</a></div><?php endif; ?><?php foreach($rows as $p): ?><a class="athlete-card" href="patinador.php?id=<?= (int)$p['id'] ?>"><div class="athlete-photo"><img src="<?= e($p['foto']) ?>" alt="Foto ilustrativa de <?= e($p['nome']) ?>"><span><?= e($p['sigla']??'ISU') ?></span></div><div class="athlete-card-info"><span class="eyebrow"><?= e($p['disciplina']) ?></span><h3><?= e($p['nome']) ?></h3><p><?= e($p['pais']) ?> · <?= e($p['equipe_nome']??'Sem equipe') ?></p><span class="card-link">Ver perfil ↗</span></div></a><?php endforeach; ?></div>
<?php require 'includes/footer.php'; ?>
